/**
 * Hash-based (post-quantum) one-time signatures for the puck: WOTS (w = 16) leaves in a Merkle tree.
 *
 * Security rests only on Keccak-256 preimage and second-preimage resistance. Shor's algorithm does not
 * break it; Grover's algorithm halves the bit strength (256 -> 128 bits). It is a simplified, XMSS-style
 * construction (tweaked hashes instead of bitmasks), written for this project and not audited.
 *
 * Byte layouts (every integer big-endian, everything concatenated without padding):
 *   sk(i)      = keccak256(0x00 || seed[32] || leaf[4] || i[1])
 *   F(x)       = keccak256(0x01 || leaf[4] || i[1] || j[1] || x[32])      one chain step, from position j to j + 1
 *   leafHash   = keccak256(0x02 || end_0 || ... || end_66)                 end_i = chain i at position 15
 *   node       = keccak256(0x03 || left[32] || right[32])
 *   message    = keccak256(PQ_TAG[32] || chainId[32] || vault[20] || leaf[4] || digest[32])
 *   digits     = 64 nibbles of message (high nibble first), then 3 checksum nibbles of sum(15 - d)
 *
 * The contract (HisnVault._pqVerify) and the firmware (hisn_pq.c) implement the same layouts.
 */
import { keccak_256 } from "@noble/hashes/sha3";
import { AbiCoder, getBytes, hexlify, keccak256, toUtf8Bytes } from "ethers";

export const PQ_W = 16;
export const PQ_LEN1 = 64;
export const PQ_LEN2 = 3;
export const PQ_LEN = PQ_LEN1 + PQ_LEN2; // 67 chains
export const PQ_TAG = keccak256(toUtf8Bytes("HISN_PQ_V1"));

export interface PqContext {
  chainId: bigint | number;
  vault: string;
}

export interface PqSignature {
  leaf: number;
  chains: string[]; // 67 x bytes32
  path: string[]; // height x bytes32, sibling at each level from the leaf up
}

function u32(n: number): Uint8Array {
  return new Uint8Array([(n >>> 24) & 255, (n >>> 16) & 255, (n >>> 8) & 255, n & 255]);
}

function cat(...parts: Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((a, p) => a + p.length, 0));
  let o = 0;
  for (const p of parts) {
    out.set(p, o);
    o += p.length;
  }
  return out;
}

function skOf(seed: Uint8Array, leaf: number, i: number): Uint8Array {
  return keccak_256(cat(new Uint8Array([0]), seed, u32(leaf), new Uint8Array([i])));
}

/** Advance chain `i` of `leaf` from position `from` by `steps`. */
export function pqChain(x: Uint8Array, leaf: number, i: number, from: number, steps: number): Uint8Array {
  const buf = new Uint8Array(1 + 4 + 1 + 1 + 32);
  buf[0] = 1;
  buf.set(u32(leaf), 1);
  buf[5] = i;
  let cur = x;
  for (let j = from; j < from + steps; j++) {
    buf[6] = j;
    buf.set(cur, 7);
    cur = keccak_256(buf);
  }
  return cur;
}

function leafHash(ends: Uint8Array[]): Uint8Array {
  return keccak_256(cat(new Uint8Array([2]), ...ends));
}

function node(l: Uint8Array, r: Uint8Array): Uint8Array {
  return keccak_256(cat(new Uint8Array([3]), l, r));
}

export function pqMessage(ctx: PqContext, leaf: number, digest: string): Uint8Array {
  const chainId = getBytes(AbiCoder.defaultAbiCoder().encode(["uint256"], [BigInt(ctx.chainId)]));
  return keccak_256(cat(getBytes(PQ_TAG), chainId, getBytes(ctx.vault), u32(leaf), getBytes(digest)));
}

export function pqDigits(msg: Uint8Array): number[] {
  const d: number[] = [];
  for (const b of msg) d.push(b >> 4, b & 15);
  let c = 0;
  for (const x of d) c += 15 - x;
  d.push((c >> 8) & 15, (c >> 4) & 15, c & 15);
  return d;
}

function leafPublic(seed: Uint8Array, leaf: number): Uint8Array {
  const ends: Uint8Array[] = [];
  for (let i = 0; i < PQ_LEN; i++) ends.push(pqChain(skOf(seed, leaf, i), leaf, i, 0, PQ_W - 1));
  return leafHash(ends);
}

/** The puck's hash-based key: a seed and the Merkle tree over 2^height one-time keys. */
export class PqKeyTree {
  readonly height: number;
  private readonly seed: Uint8Array;
  private readonly levels: Uint8Array[][];

  constructor(seed: string | Uint8Array, height: number) {
    if (height < 1 || height > 16) throw new Error("height must be 1..16");
    this.seed = typeof seed === "string" ? getBytes(seed) : seed;
    if (this.seed.length !== 32) throw new Error("seed must be 32 bytes");
    this.height = height;
    const leaves: Uint8Array[] = [];
    for (let k = 0; k < 2 ** height; k++) leaves.push(leafPublic(this.seed, k));
    this.levels = [leaves];
    for (let h = 0; h < height; h++) {
      const below = this.levels[h];
      const up: Uint8Array[] = [];
      for (let k = 0; k < below.length; k += 2) up.push(node(below[k], below[k + 1]));
      this.levels.push(up);
    }
  }

  get root(): string {
    return hexlify(this.levels[this.height][0]);
  }

  get capacity(): number {
    return 2 ** this.height;
  }

  /** Sign a vault digest with one-time key `leaf`. Never sign twice with the same leaf. */
  sign(ctx: PqContext, digest: string, leaf: number): PqSignature {
    if (leaf < 0 || leaf >= this.capacity) throw new Error("no one-time keys left");
    const digits = pqDigits(pqMessage(ctx, leaf, digest));
    const chains = digits.map((dgt, i) => hexlify(pqChain(skOf(this.seed, leaf, i), leaf, i, 0, dgt)));
    const path: string[] = [];
    let idx = leaf;
    for (let h = 0; h < this.height; h++) {
      path.push(hexlify(this.levels[h][idx ^ 1]));
      idx >>= 1;
    }
    return { leaf, chains, path };
  }
}

/** Root reached by a signature, or null if malformed. The vault compares this with its stored root. */
export function pqRecoverRoot(ctx: PqContext, digest: string, sig: PqSignature): string | null {
  if (sig.chains.length !== PQ_LEN) return null;
  const digits = pqDigits(pqMessage(ctx, sig.leaf, digest));
  const ends = digits.map((dgt, i) => pqChain(getBytes(sig.chains[i]), sig.leaf, i, dgt, PQ_W - 1 - dgt));
  let h = leafHash(ends);
  let idx = sig.leaf;
  for (const sib of sig.path) {
    h = idx & 1 ? node(getBytes(sib), h) : node(h, getBytes(sib));
    idx >>= 1;
  }
  return hexlify(h);
}

export function pqVerify(ctx: PqContext, digest: string, sig: PqSignature, root: string): boolean {
  return pqRecoverRoot(ctx, digest, sig)?.toLowerCase() === root.toLowerCase();
}

/** ABI encoding passed to the vault's `...PQ` functions: (uint32 leaf, bytes32[67] chains, bytes32[] path). */
export function encodePqSignature(sig: PqSignature): string {
  return AbiCoder.defaultAbiCoder().encode(["uint32", "bytes32[67]", "bytes32[]"], [sig.leaf, sig.chains, sig.path]);
}

export function decodePqSignature(data: string): PqSignature {
  const [leaf, chains, path] = AbiCoder.defaultAbiCoder().decode(["uint32", "bytes32[67]", "bytes32[]"], data);
  return { leaf: Number(leaf), chains: [...chains] as string[], path: [...path] as string[] };
}

/** Seed the puck derives from its ECDSA private key (firmware pq_keys.cpp does the same): keccak256("HISN_PQ_SEED" || priv). */
export function pqSeedFromKey(privateKey: string): string {
  return hexlify(keccak_256(cat(toUtf8Bytes("HISN_PQ_SEED"), getBytes(privateKey))));
}

export const PQ_DEFAULT_HEIGHT = 8;
